from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')

s=s.replace('<title>3DLite v3.97.0 L3N Deep Integrated Development</title>','<title>3DLite v3.97.3 L3N Diagnostic Learning</title>')
s=s.replace('3.97.2','3.97.3')
s=s.replace("BuildIdentity=Object.freeze({version:'3.97.0'","BuildIdentity=Object.freeze({version:'3.97.3'")

marker='__3DLiteL3NDebugRegistry3973'
if marker not in s:
    layer=r'''\n<script id="__3DLiteL3NDebugRegistry3973">\n/* 3DLite v3.97.3 — L3N Diagnostic Registry + categorized debugging learning */\n(()=>{\n  const VERSION='3.97.3';\n  const STORAGE_KEY='3dlite.l3n.debug.v1';\n  const MAX_ISSUES=400;\n  const MAX_LESSONS=200;\n  const CATEGORIES=Object.freeze({\n    model:['topology','normals','faces','vertices','weld','triangulation','uv','modifier','mesh'],\n    viewport:['black-viewport','fps','camera','controls','selection-highlight','gizmo','display','shader-preview','webgl'],\n    lighting:['contribution','attenuation','soft-shadow','shadow-acne','light-leak','bounce','exposure','sampling-noise'],\n    rendering:['stuck-render','progress','ray-count','reflection','refraction','gi-noise','shadow-noise','passes','texture-render','renderer-crash'],\n    materials:['texture','uv-scale','reflection','refraction','roughness','metalness','shader','invalid-values'],\n    rays:['direction','recursion','loop','miss','self-intersection','bvh','secondary-rays','importance-sampling'],\n    performance:['frame-time','render-time','memory','draw-calls','geometry','shader-cost','recalculation','cpu-gpu','long-task'],\n    ui:['button','numeric-field','state','missing-panel','hotkey','undo-ui','context-menu'],\n    editing:['vertex-selection','target-weld','edge-selection','polygon-selection','transform','snap','edit-mode'],\n    history:['undo','redo','mesh-corruption','command-registration','duplicate-state'],\n    runtime:['tdz','reference','dependency','duplicate-init','animation-loop','bootstrap-order','boot-timeout','exception','promise'],\n    io:['import','export','materials','scale','coordinates','normals'],\n    l3n:['baseline','stale-version','false-regression','scoring','evidence','repeated-fix','contradiction','regression']\n  });\n\n  const state={version:VERSION,issues:[],lessons:[],counts:{},lastReport:null};\n  for(const key of Object.keys(CATEGORIES))state.counts[key]=0;\n\n  const safeClone=v=>{try{return JSON.parse(JSON.stringify(v));}catch(_){return String(v);}};\n  const now=()=>Date.now();\n  function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify({version:VERSION,issues:state.issues.slice(-MAX_ISSUES),lessons:state.lessons.slice(-MAX_LESSONS)}));}catch(_){}}\n  function restore(){try{const x=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(!x)return;state.issues=Array.isArray(x.issues)?x.issues.slice(-MAX_ISSUES):[];state.lessons=Array.isArray(x.lessons)?x.lessons.slice(-MAX_LESSONS):[];for(const k of Object.keys(state.counts))state.counts[k]=state.issues.filter(i=>i.category===k).length;}catch(_){}}\n\n  function classify(text=''){\n    const t=String(text).toLowerCase();\n    if(/light|shadow|exposure/.test(t))return ['lighting',/shadow/.test(t)?'shadow-noise':'contribution'];\n    if(/ray|bvh|intersection|bounce/.test(t))return ['rays',/bvh/.test(t)?'bvh':'direction'];\n    if(/render|denoise|reflection|refraction|gi\b|pass/.test(t))return ['rendering',/reflection/.test(t)?'reflection':/refraction/.test(t)?'refraction':'renderer-crash'];\n    if(/material|texture|roughness|metalness|shader|\buv\b/.test(t))return ['materials',/texture/.test(t)?'texture':'shader'];\n    if(/mesh|topology|normal|vertex|face|weld|triang/.test(t))return ['model',/normal/.test(t)?'normals':/weld/.test(t)?'weld':'mesh'];\n    if(/viewport|canvas|webgl|camera|gizmo/.test(t))return ['viewport',/webgl|canvas/.test(t)?'webgl':'display'];\n    if(/undo|redo|history/.test(t))return ['history',/redo/.test(t)?'redo':'undo'];\n    if(/select|target weld|transform|snap|edit mode/.test(t))return ['editing',/target weld/.test(t)?'target-weld':'transform'];\n    if(/fps|frame|slow|performance|memory|draw call|long task/.test(t))return ['performance',/frame|fps/.test(t)?'frame-time':'long-task'];\n    if(/import|export/.test(t))return ['io',/import/.test(t)?'import':'export'];\n    if(/baseline|regress|learning|l3n|version/.test(t))return ['l3n',/version/.test(t)?'stale-version':'regression'];\n    if(/button|panel|menu|hotkey|field|ui/.test(t))return ['ui','state'];\n    return ['runtime','exception'];\n  }\n\n  function lessonFrom(issue){\n    const key=issue.category+':'+issue.subtype;\n    const prior=state.lessons.find(x=>x.key===key);\n    if(prior){prior.count++;prior.lastSeen=issue.detectedAt;prior.lastSeverity=issue.severity;prior.status=issue.status;return prior;}\n    const lesson={key,category:issue.category,subtype:issue.subtype,count:1,firstSeen:issue.detectedAt,lastSeen:issue.detectedAt,lastSeverity:issue.severity,status:issue.status,rule:'Preserve successful fixes; avoid repeating failed patterns for '+key};\n    state.lessons.push(lesson);\n    if(state.lessons.length>MAX_LESSONS)state.lessons.shift();\n    return lesson;\n  }\n\n  function register(input={}){\n    const guessed=classify(input.message||input.subtype||input.source||'');\n    const category=CATEGORIES[input.category]?input.category:guessed[0];\n    const subtype=String(input.subtype||guessed[1]||'unknown');\n    const issue={id:'l3n-'+now().toString(36)+'-'+Math.random().toString(36).slice(2,7),category,subtype,severity:String(input.severity||'medium'),subsystem:String(input.subsystem||category),detectedAt:now(),reproduced:input.reproduced!==false,regression:!!input.regression,source:String(input.source||'runtime'),message:String(input.message||''),evidence:safeClone(input.evidence||{}),attemptedFixes:Array.isArray(input.attemptedFixes)?safeClone(input.attemptedFixes):[],successfulFix:input.successfulFix||null,status:String(input.status||'open')};\n    state.issues.push(issue);\n    if(state.issues.length>MAX_ISSUES)state.issues.shift();\n    state.counts[category]=(state.counts[category]||0)+1;\n    const lesson=lessonFrom(issue);\n    try{window.ThreeDLiteL3NTargetLearning?.record?.(15,'learning',category+'/'+subtype+': '+(issue.message||issue.status));}catch(_){}\n    persist();\n    return Object.freeze({...issue,lesson:Object.freeze({...lesson})});\n  }\n\n  function resolve(id,fix=''){const x=state.issues.find(i=>i.id===id);if(!x)return false;x.status='resolved';x.successfulFix=String(fix||'resolved');lessonFrom(x);persist();return true;}\n  function snapshot(){return Object.freeze({version:VERSION,categories:CATEGORIES,counts:Object.freeze({...state.counts}),open:state.issues.filter(i=>i.status!=='resolved').length,total:state.issues.length,issues:Object.freeze(state.issues.map(i=>Object.freeze({...i}))),lessons:Object.freeze(state.lessons.map(l=>Object.freeze({...l}))),lastReport:state.lastReport});}\n  function clear(){state.issues.length=0;state.lessons.length=0;for(const k of Object.keys(state.counts))state.counts[k]=0;state.lastReport=null;persist();return true;}\n\n  function ingestRuntimeReport(report){\n    if(!report||typeof report!=='object')return false;\n    state.lastReport={at:now(),version:report.version||null,passed:report.passed!==false};\n    if(report.version&&report.version!==VERSION)register({category:'l3n',subtype:'stale-version',severity:'high',regression:true,source:'runtime-learning',message:'Runtime Learning version '+report.version+' differs from '+VERSION,evidence:{reportVersion:report.version,currentVersion:VERSION}});\n    for(const t of (report.tests||[])){if(t&&t.passed===false)register({source:'runtime-test',message:t.name||'runtime test failed',severity:'high',regression:true,evidence:t});}\n    const comps=report.comparison?.comparisons||{};\n    for(const [name,c] of Object.entries(comps)){if(c?.status==='regressed'){const pct=Math.abs(Number(c.percent)||0);const micro=/^test:/.test(name);if(micro&&pct>0){register({category:'l3n',subtype:'false-regression',severity:'low',source:'runtime-comparison',message:name+' reported percentage regression; retain absolute-time context',evidence:c,regression:true});}else register({source:'runtime-comparison',message:name+' regressed',severity:'medium',evidence:c,regression:true});}}\n    if(report.frame?.slowFrames>0||report.frame?.severeFrames>0)register({category:'performance',subtype:'frame-time',severity:report.frame.severeFrames>0?'high':'medium',source:'runtime-learning',message:'Slow/severe frames detected',evidence:report.frame,regression:true});\n    persist();\n    return true;\n  }\n\n  function watchRuntimeReport(){\n    const attach=()=>{const node=document.querySelector('#l3nRuntimeMachineReport');if(!node||node.__l3nDebugObserved)return;node.__l3nDebugObserved=true;const read=()=>{try{const raw=(node.value||node.textContent||'').trim();if(raw&&raw[0]==='{')ingestRuntimeReport(JSON.parse(raw));}catch(_){}};new MutationObserver(read).observe(node,{subtree:true,childList:true,characterData:true,attributes:true});node.addEventListener?.('change',read);};\n    attach();setTimeout(attach,500);setTimeout(attach,2000);\n  }\n\n  restore();\n  window.addEventListener('error',e=>register({source:'window.error',message:e.message||'runtime error',severity:'high',evidence:{filename:e.filename,lineno:e.lineno,colno:e.colno}}));\n  window.addEventListener('unhandledrejection',e=>register({source:'unhandledrejection',message:String(e.reason?.message||e.reason||'unhandled promise rejection'),severity:'high',subtype:'promise'}));\n  document.addEventListener('DOMContentLoaded',()=>{const canvas=document.querySelector('#viewport canvas');if(canvas){canvas.addEventListener('webglcontextlost',e=>register({category:'viewport',subtype:'webgl',severity:'critical',source:'webgl',message:'WebGL context lost',evidence:{statusMessage:e.statusMessage||''}}));canvas.addEventListener('webglcontextrestored',()=>register({category:'viewport',subtype:'webgl',severity:'info',source:'webgl',message:'WebGL context restored',status:'resolved'}));}watchRuntimeReport();});\n  try{if('PerformanceObserver' in window){const po=new PerformanceObserver(list=>{for(const x of list.getEntries()){if(x.duration>=100)register({category:'performance',subtype:'long-task',severity:x.duration>=250?'high':'medium',source:'performance-observer',message:'Long main-thread task '+x.duration.toFixed(1)+' ms',evidence:{duration:x.duration,startTime:x.startTime}});}});po.observe({entryTypes:['longtask']});}}catch(_){}\n\n  window.ThreeDLiteL3NDebugRegistry=Object.freeze({version:VERSION,categories:CATEGORIES,register,resolve,snapshot,clear,classify,ingestRuntimeReport});\n  window.__3DLiteL3NDebugSnapshot=()=>window.ThreeDLiteL3NDebugRegistry.snapshot();\n  try{window.ThreeDLiteL3NTargetLearning?.record?.(15,'integrated','categorized diagnostic registry active: model, viewport, lighting, rendering, materials, rays, performance, UI, editing, history, runtime, I/O, L3N');}catch(_){}\n})();\n</script>\n'''
    pos=s.lower().rfind('</body>')
    if pos<0: raise SystemExit('missing </body>')
    s=s[:pos]+layer+s[pos:]

required=[
    "version:'3.97.3'",
    '__3DLiteL3NDebugRegistry3973',
    'ThreeDLiteL3NDebugRegistry',
    'ingestRuntimeReport',
    'lighting:[',
    'performance:[',
]
for x in required:
    if x not in s: raise SystemExit('missing required marker: '+x)

p.write_text(s,encoding='utf-8')
print('patched index.html for v3.97.3 L3N diagnostic registry')
